package vn.com.apartment.billing;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;
@Entity @Table(name="receivable_items")
public class ReceivableItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="receivable_id") private Receivable receivable;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="service_type_id") private ServiceType serviceType;@Column(nullable=false,length=300) private String description;@Column(nullable=false,precision=18,scale=3) private BigDecimal quantity;@Column(name="unit_price",nullable=false,precision=18,scale=2) private BigDecimal unitPrice;@Column(nullable=false,precision=18,scale=2) private BigDecimal amount;@Column(name="paid_amount",nullable=false,precision=18,scale=2) private BigDecimal paidAmount=BigDecimal.ZERO;@Column(name="service_period_start") private LocalDate servicePeriodStart;@Column(name="service_period_end") private LocalDate servicePeriodEnd;protected ReceivableItem(){}ReceivableItem(Receivable r,ServiceType t,String d,BigDecimal q,BigDecimal p,LocalDate s,LocalDate e){receivable=r;serviceType=t;description=d;quantity=q;unitPrice=p;amount=q.multiply(p);servicePeriodStart=s;servicePeriodEnd=e;}public void recordPayment(BigDecimal value){if(value.signum()<=0||value.compareTo(outstanding())>0)throw new IllegalArgumentException("Số tiền thu không hợp lệ cho dịch vụ này.");paidAmount=paidAmount.add(value);}public BigDecimal outstanding(){return amount.subtract(paidAmount);}public Long getId(){return id;}public String getDescription(){return description;}public BigDecimal getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getAmount(){return amount;}public BigDecimal getPaidAmount(){return paidAmount;}public Receivable getReceivable(){return receivable;}}
